def min_left_rotations_to_sort(lst):
    n = len(lst)
    if n <= 1:
        return 0
    for k in range(n):
        rotated = lst[k:] + lst[:k]
        if rotated == sorted(rotated):
            return k
    return -1

def count_distinct_rotations(lst):
    n = len(lst)
    if n == 0:
        return 1
    distinct = set()
    for k in range(n):
        distinct.add(tuple(lst[k:] + lst[:k]))
    return len(distinct)

def moving_average_round_int(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    result = []
    for i in range(n - k + 1):
        window = lst[i:i+k]
        result.append(round(sum(window) / k))
    return result

