def moving_average_floor(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    result = []
    for i in range(n - k + 1):
        window = lst[i:i+k]
        result.append(sum(window) // k)
    return result

def trailing_average_with_padding(lst, k):
    n = len(lst)
    if n == 0:
        return []
    result = []
    for i in range(n):
        start = max(0, i - k + 1)
        window = lst[start:i+1]
        result.append(round(sum(window) / len(window), 2))
    return result

def center_moving_average(lst, radius):
    n = len(lst)
    if n == 0:
        return []
    result = []
    for i in range(n):
        start = max(0, i - radius)
        end = min(n - 1, i + radius)
        window = lst[start:end+1]
        result.append(round(sum(window) / len(window)))
    return result

def remove_every_kth_1indexed(lst, k):
    if k <= 0:
        return lst[:]
    return [x for i, x in enumerate(lst, start=1) if i % k != 0]

def remove_every_kth_0indexed(lst, k):
    if k <= 0:
        return lst[:]
    return [x for i, x in enumerate(lst) if i % k != 0]

def keep_every_kth(lst, k):
    if k <= 0:
        return []
    return [x for i, x in enumerate(lst, start=1) if i % k == 0]

def remove_every_kth_starting_at(lst, k, start):
    if k <= 0:
        return lst[:]
    to_remove = set()
    i = start
    n = len(lst)
    while i < n:
        to_remove.add(i)
        i += k
    return [x for idx, x in enumerate(lst) if idx not in to_remove]

def rle_encode(lst):
    if not lst:
        return []
    result = []
    current = lst[0]
    count = 1
    for x in lst[1:]:
        if x == current:
            count += 1
        else:
            result.append([current, count])
            current = x
            count = 1
    result.append([current, count])
    return result

def rle_decode(pairs):
    result = []
    for value, count in pairs:
        result.extend([value] * count)
    return result

def rle_longest_run_value(lst):
    if not lst:
        return None
    best_value = lst[0]
    best_len = 0
    current = lst[0]
    count = 1
    for x in lst[1:]:
        if x == current:
            count += 1
        else:
            if count > best_len:
                best_len = count
                best_value = current
            current = x
            count = 1
    if count > best_len:
        best_len = count
        best_value = current
    return best_value

def collapse_consecutive_duplicates(lst):
    if not lst:
        return []
    result = [lst[0]]
    for x in lst[1:]:
        if x != result[-1]:
            result.append(x)
    return result

def second_largest_distinct(lst):
    distinct = sorted(set(lst), reverse=True)
    if len(distinct) < 2:
        return None
    return distinct[1]

def second_smallest_distinct(lst):
    distinct = sorted(set(lst))
    if len(distinct) < 2:
        return None
    return distinct[1]

def kth_largest_distinct(lst, k):
    if k < 1:
        return None
    distinct = sorted(set(lst), reverse=True)
    if k > len(distinct):
        return None
    return distinct[k-1]

def balance_index(lst):
    n = len(lst)
    total = sum(lst)
    left = 0
    for i in range(n):
        right = total - left - lst[i]
        if left == right:
            return i
        left += lst[i]
    return -1
